INSERT INTO `page_sections` VALUES (1,'home','stats','Chiffres clés',NULL,NULL,1,1,'[{\"l\": \"Élèves inscrits\", \"n\": \"1 200+\"}, {\"l\": \"Enseignants qualifiés\", \"n\": \"85\"}, {\"l\": \"D\'expérience\", \"n\": \"27 ans\"}, {\"l\": \"Taux de réussite au bac\", \"n\": \"98%\"}]','2026-05-17 16:56:23','2026-05-17 16:56:23'),(2,'home','cycles','Nos cycles','De la maternelle au baccalauréat',NULL,1,2,'[{\"d\": \"L\'éveil par le jeu et la découverte dans un cadre sécurisant.\", \"i\": \"🌱\", \"t\": \"Préscolaire\", \"age\": \"3 – 5 ans\", \"color\": \"#F59E0B\", \"items\": [\"Motricité fine & globale\", \"Langage oral\", \"Socialisation\", \"Activités créatives\"]}, {\"d\": \"Les bases solides en lecture, écriture, mathématiques et sciences.\", \"i\": \"📖\", \"t\": \"Fondamental\", \"age\": \"6 – 11 ans\", \"color\": \"#10B981\", \"items\": [\"Français & Créole\", \"Mathématiques\", \"Sciences naturelles\", \"Histoire-Géographie\"]}, {\"d\": \"Préparation rigoureuse au baccalauréat et à l\'université.\", \"i\": \"🎓\", \"t\": \"Secondaire\", \"age\": \"12 – 18 ans\", \"color\": \"#3B82F6\", \"items\": [\"Séries scientifique & littéraire\", \"Langues vivantes\", \"Informatique\", \"Orientation universitaire\"]}]','2026-05-17 16:56:23','2026-05-17 16:56:23'),(3,'home','features','Nos atouts','Pourquoi choisir Le Mignon ?',NULL,1,3,'[{\"d\": \"Tous nos professeurs sont diplômés d\'État.\", \"i\": \"👨‍🏫\", \"t\": \"Enseignants certifiés\"}, {\"d\": \"Fonds documentaire riche et accès numérique.\", \"i\": \"📚\", \"t\": \"Bibliothèque & ressources\"}, {\"d\": \"Réunions trimestrielles et bulletins détaillés.\", \"i\": \"👨‍👩‍👧\", \"t\": \"Suivi parental\"}, {\"d\": \"Salles équipées, labos, complexe sportif.\", \"i\": \"🏟️\", \"t\": \"Infrastructures modernes\"}, {\"d\": \"Accès sécurisé et surveillance permanente.\", \"i\": \"🔒\", \"t\": \"Sécurité & encadrement\"}]','2026-05-17 16:56:23','2026-05-17 16:56:23'),(4,'home','activities','Vie scolaire','L\'école, au-delà des cours',NULL,1,4,'[{\"t\": \"Sport & EPS\", \"img\": \"https://images.unsplash.com/photo-1571019614242-c5c5dee9f50b?w=600&q=80\", \"tag\": \"Parascolaire\", \"desc\": \"\"}, {\"t\": \"Arts plastiques\", \"img\": \"https://images.unsplash.com/photo-1513364776144-60967b0f800f?w=600&q=80\", \"tag\": \"Créativité\", \"desc\": \"\"}, {\"t\": \"Club de lecture\", \"img\": \"https://images.unsplash.com/photo-1456513080510-7bf3a84b82f8?w=600&q=80\", \"tag\": \"Culture\", \"desc\": \"\"}, {\"t\": \"Concours scolaires\", \"img\": \"https://images.unsplash.com/photo-1606761568499-6d2451b23c66?w=600&q=80\", \"tag\": \"Excellence\", \"desc\": \"\"}]','2026-05-17 16:56:23','2026-05-17 16:56:23'),(5,'home','testimonials','Témoignages','Ce que disent les familles',NULL,1,5,'[{\"n\": \"Marie-Claire Fortuné\", \"r\": \"Parent d\'élève — Cycle secondaire\", \"t\": \"Mes enfants s\'épanouissent vraiment ici.\"}, {\"n\": \"Jean-Pierre Alexis\", \"r\": \"Parent d\'élève — Cycle fondamental\", \"t\": \"L\'encadrement est sérieux et bienveillant.\"}, {\"n\": \"Nadège Saint-Hilaire\", \"r\": \"Parent d\'élève — Préscolaire & Primaire\", \"t\": \"Une école qui tient ses promesses.\"}]','2026-05-17 16:56:23','2026-05-17 16:56:23'),(6,'home','values','Nos valeurs',NULL,NULL,1,6,'[{\"i\": \"🎯\", \"t\": \"Excellence\"}, {\"i\": \"🤝\", \"t\": \"Bienveillance\"}, {\"i\": \"💡\", \"t\": \"Innovation\"}, {\"i\": \"🌍\", \"t\": \"Citoyenneté\"}]','2026-05-17 16:56:23','2026-05-17 16:56:23'),(7,'formations','formation_atouts','Nos atouts',NULL,NULL,1,1,'[{\"d\": \"100% titulaires d\'un Master ou d\'une agrégation.\", \"i\": \"👨‍🏫\", \"t\": \"Enseignants certifiés\"}, {\"d\": \"25 élèves max pour un suivi individualisé.\", \"i\": \"🏫\", \"t\": \"Petits groupes\"}, {\"d\": \"Salles numériques, labos, bibliothèque, coworking.\", \"i\": \"💻\", \"t\": \"Équipements modernes\"}, {\"d\": \"3 500+ anciens dans les meilleures entreprises.\", \"i\": \"🤝\", \"t\": \"Réseau alumni\"}]','2026-05-17 16:56:23','2026-05-17 16:56:23');
