DROP TABLE IF EXISTS `paiements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `paiements` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `annee_academique` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `classe` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `faculte_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cours` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `niveau_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mois` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `etudiant_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `paiement_details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `last_paiement_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `paiements_annee_academique_etudiant_id_unique` (`annee_academique`,`etudiant_id`),
  KEY `paiements_etudiant_id_foreign` (`etudiant_id`),
  KEY `paiements_last_paiement_key_index` (`last_paiement_key`),
  KEY `paiements_classe_index` (`classe`),
  KEY `paiements_niveau_id_index` (`niveau_id`),
  CONSTRAINT `paiements_classe_foreign` FOREIGN KEY (`classe`) REFERENCES `classes` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `paiements_etudiant_id_foreign` FOREIGN KEY (`etudiant_id`) REFERENCES `etudiants` (`id`),
  CONSTRAINT `paiements_niveau_id_foreign` FOREIGN KEY (`niveau_id`) REFERENCES `niveaux` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `paiements_chk_1` CHECK (json_valid(`mois`)),
  CONSTRAINT `paiements_chk_2` CHECK (json_valid(`paiement_details`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
